                { id = "pal_pro_conjuros_5", level = 5, name = "Conjuros de camino (Proteccion)", type = "informativo", grantedSpells = { "castigo_marcador", "guardian_del_rey" }, description = "Nivel 5: Castigo marcador y Guardian del rey. Los conjuros de camino siempre los tienes preparados y NO cuentan contra los conjuros de paladin que puedes preparar.", spellGrants = { { level = 2, ids = { "castigo_marcador", "guardian_del_rey" } } }, effects = {} },
            { id = "pal_pro_canalizar", level = 3, name = "Canalizar divinidad", type = "pasivo", description = "Cuando tomas este camino al 3er nivel, obtienes las siguientes dos opciones de Canalizar Divinidad.\n\n***Consagración.*** Como acción, puedes usar tu Canalizar Divinidad para consagrar el suelo a tu alrededor en un radio de 9 metros. Cada criatura de tu elección dentro del rango debe realizar una tirada de salvación de Destreza, recibiendo daño radiante igual a tu nivel de paladín + Mod. Carisma en una tirada fallida, o la mitad del daño en una exitosa. Además, cada criatura aliada dentro del rango gana un número de puntos de golpe temporales igual a la mitad de tu nivel de paladín + Mod. Carisma.\n\n***Escudo sagrado.*** Como acción adicional, invocas la luz para protegerte. Durante 1 minuto, las tiradas de ataque contra ti se realizan con desventaja. Además, una vez por turno, cuando una criatura falle un ataque cuerpo a cuerpo contra ti, puedes infligirle daño radiante igual a 1d6 más la mitad de tu nivel de paladín.", effects = {} },
