            { id = "pal_pro_escudo_sagrado", level = 3, name = "Escudo Sagrado", cast = "accion_adicional", type = "accion", resourceKey = "channel_divinity", resourceCost = 1, selfCondition = { id = "escudo_sagrado", duration = "rounds", turns = 10 }, description = "Accion adicional: durante 1 minuto, las tiradas de ataque contra ti se hacen con desventaja. Ademas, una vez por turno, cuando una criatura te ataque puedes infligirle dano radiante igual a 1d6 mas la mitad de tu nivel de paladin.", effects = {} },
            { id = "pal_pro_bastion", level = 3, name = "Bastion divino", type = "recurso", description = "En el nivel 3, cuando golpeas a una criatura con un ataque cuerpo a cuerpo, puedes gastar un espacio de conjuro para infligir daño radiante al objetivo, además del daño del arma. El daño adicional es de 2d6 por un espacio de conjuro de 1er nivel, más 1d6 por cada nivel de conjuro superior al 1º, hasta un máximo de 6d6.\n\nAdemás, la criatura tiene desventaja en las tiradas de ataque contra criaturas que no seas tú hasta el final de tu próximo turno. Por cada nivel de conjuro superior al 1º, puedes elegir una criatura adicional dentro de 3 metros de ti para que sufra este efecto hasta el final de tu próximo turno.\n\nUn ataque cuerpo a cuerpo puede beneficiarse de tu Golpe del Cruzado o de tu Bastión Divino, pero solo uno de estos efectos puede aplicarse a un ataque.", effects = {
