                { id = "pal_ret_conjuros_5", level = 5, name = "Conjuros de camino (Retribucion)", type = "informativo", grantedSpells = { "arma_magica", "golpe_justo" }, description = "Nivel 5: Arma magica y Golpe de cruzado (el castigo justo del manual: texto identico del capitulo 6, +2d6 radiante y ventaja al siguiente ataque). Los conjuros de camino siempre los tienes preparados y NO cuentan contra los conjuros de paladin que puedes preparar.", spellGrants = { { level = 2, ids = { "arma_magica", "golpe_justo" } } }, effects = {} },
            { id = "pal_ret_canalizar", level = 3, name = "Canalizar divinidad", type = "pasivo", description = "Cuando tomas este camino al 3er nivel, obtienes las siguientes dos opciones de Canalizar Divinidad.\n\n ***Veredicto del Templario.*** Como acción adicional, puedes emitir un veredicto contra una criatura que puedas ver a 3 metros de ti. Obtienes ventaja en las tiradas de ataque contra la criatura durante 1 minuto, hasta que caiga a 0 puntos de golpe o quede inconsciente.\n\n***Rechazar lo profano.*** Como acción, presentas tu símbolo sagrado y pronuncias una oración censurando a demonios y no muertos, usando tu Canalizar Divinidad. Cada demonio o no muerto que pueda verte o escucharte a 9 metros debe hacer una tirada de salvación de Sabiduría. Si falla, queda apartado durante 1 minuto o hasta que reciba daño.\n\nUna criatura apartada debe gastar sus turnos intentando alejarse lo más posible de ti, y no puede acercarse voluntariamente a un espacio a 9 metros de ti. Tampoco puede realizar reacciones. Para su acción, solo puede usar la acción de Correr o intentar escapar de un efecto que le impida moverse. Si no hay adónde moverse, puede usar la acción de Esquivar.", effects = {} },
            { id = "pal_ret_veredicto", level = 3, name = "Veredicto del Templario", cast = "accion_adicional", type = "accion", resourceKey = "channel_divinity", resourceCost = 1, dcAbility = "Carisma", area = { shape = "other", sizeText = "Objetivo", resolution = "auto", conditionId = "veredicto", conditionDuration = "rounds", conditionTurns = 10 }, description = "Accion adicional: emites un veredicto contra una criatura a 9 metros. Obtienes ventaja en las tiradas de ataque contra ella durante 1 minuto, hasta que caiga a 0 puntos de golpe o quede inconsciente.", effects = {} },
            { id = "pal_ret_rechazar", level = 3, name = "Rechazar lo Profano", cast = "accion", type = "accion", resourceKey = "channel_divinity", resourceCost = 1, dcAbility = "Carisma", area = { shape = "sphere", sizeText = "9 m de radio", resolution = "save", saveAbility = "Sabiduria", success = "none", conditionId = "apartado", conditionDuration = "rounds", conditionTurns = 10 }, description = "Accion: presentas tu simbolo sagrado. Cada demonio o no-muerto a 9 metros que pueda verte u oirte hace una salvacion de Sabiduria; si falla, queda apartado durante 1 minuto o hasta que reciba dano. Una criatura apartada gasta sus turnos alejandose de ti lo mas posible y no puede acercarse voluntariamente.", effects = {} },
