    features = {
        { id = "pal_sentido_divino", level = 1, name = "Sentido divino", cast = "accion", type = "informativo", description = "La presencia de un mal poderoso se registra en tus sentidos como un hedor nocivo, y el bien poderoso resuena como música celestial en tus oídos. Como acción, puedes abrir tu percepción para detectar tales fuerzas. Hasta el final de tu siguiente turno, conoces la ubicación de cualquier celestial, infernal o no-muerto en un radio de 18 metros que no esté bajo cobertura total. Conoces el tipo (celestial, infernal o no-muerto) de cualquier ser cuya presencia detectes, pero no su identidad (como el demonio Illidan Tempestira, por ejemplo). Dentro del mismo radio, también detectas la presencia de cualquier lugar u objeto que haya sido consagrado o profanado, como con el hechizo *santuario*.\n\nPuedes usar esta característica un número de veces igual a 1 + Mod. Carisma. Cuando terminas un descanso largo, recuperas todos los usos gastados.", uses = { base = 1, ability = "Carisma", min = 1, recharge = "long" }, effects = {} },
