        { id = "pal_guerrero_bendito_trucos", requiresOption = "guerrero_bendito", level = 2, name = "Guerrero Bendito: trucos", type = "choice", icon = "ability_paladin_veneration", aboutHidden = true, rechooseOnLevelUp = "paladin", description = "Aprendes dos trucos de tu elección de la lista de conjuros de sacerdote. Cuentan como conjuros de paladín para ti, y el Carisma es tu habilidad de lanzamiento de conjuros para ellos. Siempre que ganes un nivel en esta clase, puedes reemplazar uno de estos trucos por otro truco de la lista de sacerdote.", effects = {}, choice = {
            slots = 2,
            extraFrom = "cantrip:Sacerdote",
            options = {},
        } },
        { id = "pal_lanzamiento_conjuros", level = 2, name = "Lanzamiento de conjuros", type = "pasivo", description = "A partir del 2º nivel, has aprendido a extraer magia divina mediante la meditación y la oración para lanzar conjuros como un sacerdote. Consulta [las reglas generales de lanzamiento de conjuros](reglas.html#conjuros); la lista de conjuros del paladín está al final de esta ficha.\n\n### Preparar y lanzar conjuros\nLa tabla del Paladín muestra cuántos espacios de conjuro tienes para lanzar tus conjuros. Para lanzar uno de tus conjuros de paladín de 1er nivel o superior, debes gastar un espacio de conjuro del nivel del conjuro o superior. Recuperas todos los espacios de conjuro gastados cuando terminas un descanso largo.\n\nPreparas la lista de conjuros de paladín que están disponibles para que los lances, eligiendo de la lista de conjuros de paladín. Cuando lo haces, elige un número de conjuros de paladín igual a Mod. Carisma + la mitad de tu nivel de paladín, redondeado hacia abajo (mínimo de un conjuro). Los conjuros deben ser de un nivel para el cual tengas espacios de conjuro.\n\nPor ejemplo, si eres un paladín de 5º nivel, tienes cuatro espacios de conjuro de 1er nivel y dos de 2º nivel. Con un Carisma de 14, tu lista de conjuros preparados puede incluir cuatro conjuros de 1er o 2º nivel, en cualquier combinación. Si preparas el conjuro de 1er nivel *curar heridas*, puedes lanzarlo usando un espacio de conjuro de 1er nivel o de 2º nivel. Lanzar el conjuro no lo elimina de tu lista de preparados.\n\nPuedes cambiar tu lista de conjuros preparados cuando termines un descanso largo. Preparar una nueva lista de conjuros de paladín requiere tiempo dedicado a la oración y la meditación: al menos 1 minuto por nivel de conjuro para cada conjuro en tu lista.\n\n### Habilidad para lanzar conjuros\nEl Carisma es tu habilidad de lanzamiento de conjuros para tus conjuros de paladín, ya que su poder proviene de la fuerza de tus convicciones. Usas tu Carisma siempre que un conjuro se refiera a tu habilidad para lanzarlo. Además, usas Mod. Carisma para establecer la CD de salvación contra tus conjuros de paladín y cuando hagas una tirada de ataque con uno.\n\n**CD de Salvación de Conjuro** = 8 + Bonus Competencia + Mod. Carisma\n\n**Modificador de Ataque con Conjuros** = Bonus Competencia + Mod. Carisma\n\n### Enfoque para conjuros\nPuedes usar un símbolo sagrado como enfoque para lanzar tus conjuros de paladín. Además de los símbolos sagrados presentes en el *Manual del Jugador*, puedes usar un libram como tu símbolo sagrado; un libram cuesta 5 po y pesa 1,4 kg.", effects = {} },
        { id = "pal_golpe_cruzado", level = 2, name = "Golpe del cruzado", type = "pasivo", description = "A partir del 2º nivel, cuando golpeas a una criatura con un ataque cuerpo a cuerpo, puedes gastar un espacio de conjuro para infligir daño radiante al objetivo, además del daño del arma. El daño adicional es de 2d8 por un espacio de conjuro de 1er nivel, más 1d8 por cada nivel de conjuro superior a 1º, hasta un máximo de 6d8. El daño de Golpe del Cruzado aumenta en 1d8 si el objetivo es un no-muerto o un infernal.", effects = {
            { kind = "conditionalWeaponDamage", id = "smite", label = "Golpe del Cruzado", count = 2, die = 8, damageType = "radiante", spellLevelCost = "level", minLevel = 1, maxSpellLevel = true, countPerLevel = 1, extraCountOffset = 1, maxCount = 6 },
        } },
        { id = "pal_camino_sagrado", subclassMarker = true, level = 3, name = "Camino sagrado", type = "recurso", description = "Cuando alcanzas el 3er nivel, comienzas un camino sagrado dentro de la iglesia. Elige el Camino de lo Sagrado, el Camino de la Protección o el Camino de la Retribución, todos detallados al final de la descripción de la clase.\n\nTu elección te otorga características en el 3er nivel y nuevamente en el 7º, 15º y 20º nivel. Estas características incluyen conjuros de camino y la característica Canalizar Divinidad.\n\n### Conjuros de camino\nCada camino tiene una lista de conjuros asociados que se escriben en tu libram en los niveles especificados en la descripción del camino. Una vez que un conjuro de camino ha sido escrito en tu libram, siempre lo tienes preparado. Los conjuros de camino no cuentan contra el número de conjuros que puedes preparar cada día.\n\nSi adquieres un conjuro de camino que no aparece en la lista de conjuros de paladín, el conjuro aún así es considerado un conjuro de paladín para ti.\n\n### Canalizar divinidad\nTu camino te permite canalizar energía divina para alimentar efectos mágicos. Cada opción de Canalizar Divinidad proporcionada por tu camino explica cómo usarla.\n\nCuando usas tu Canalizar Divinidad, eliges qué opción usar. Luego debes terminar un descanso corto o largo para usar Canalizar Divinidad de nuevo.\n\nAlgunos efectos de Canalizar Divinidad requieren tiradas de salvación. Cuando usas dicho efecto de esta clase, la CD es igual a la CD de salvación de conjuros de tu paladín.", effects = {
            { kind = "resourceMax", resource = "channel_divinity", value = 1, stack = "max" },
        } },
